// Worker entry: the OpenNext app for requests plus the nightly retention cron (#27).
// `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore The generated file does not exist until the OpenNext build runs.
import { default as handler } from "./.open-next/worker.js";
import {
  handleRetentionCron,
  type RetentionExecutionContext,
  type RetentionScheduledController,
  type RetentionScheduledEnv,
} from "./src/lib/retention/scheduled";

export default {
  fetch: handler.fetch,
  scheduled(
    controller: RetentionScheduledController,
    env: RetentionScheduledEnv,
    ctx: RetentionExecutionContext,
  ): Promise<void> {
    return handleRetentionCron(controller, env, ctx);
  },
};
